// Renders the script prompt from CONTROL config. No prompt text lives in this node.
// Records come from 1d. Approval Check (route = generate only), NOT from $input - node 2 sits between them and
// returns Viral Library rows, so $input here is patterns, not Reel Engine records.
// Records held at a gate (not approved, second rejection) never reach the model call.
// A fixed source-use guard is appended to every rendered prompt so the reference
// transcript cannot be reproduced regardless of which skill template is configured.
// mode = regenerate appends the previous script and Script_Feedback (one automatic rewrite, T-43).

const records = $('1d. Approval Check').all().map(i => i.json).filter(r => r && r.id && r.route === 'generate');
const patterns = $('2. Get Viral Patterns & Transcripts').all();

function withDefaults(obj, cfg) {
  const s = (cfg || {}).script || {};
  return {
    model: s.model || 'gpt-4.1-mini',
    temperature: (s.temperature !== undefined && s.temperature !== null) ? s.temperature : 0.7,
    max_tokens: s.max_tokens || 2500,
    system_prompt: s.system_prompt || '',
    words_per_minute: s.words_per_minute || 130,
    max_script_chars: s.max_script_chars || 5000,
    prompt: '',
    ...obj
  };
}

if (!records.length) {
  return [{ json: withDefaults({ _skip: true, cfg: {}, record_id: '', reason: 'No Reel Engine records reached this node.' }, {}) }];
}

const usable = patterns.filter(p => {
  const t = (p.json['Transcript'] || '').trim();
  return t !== '' && t !== 'TRANSCRIPT_UNAVAILABLE';
});
const pool = usable.length > 0 ? usable : patterns;

const out = [];

for (const record of records) {
  const cfg = record.cfg || {};
  const s = cfg.script || {};
  const recordId = record.id || '';

  if (!pool.length) {
    out.push({ json: withDefaults({ _skip: true, cfg: cfg, record_id: recordId, reason: 'No viral patterns available.' }, cfg) });
    continue;
  }

  const pattern = pool[Math.floor(Math.random() * pool.length)].json;

  const contentType = record['Content Type'] || 'Video';
  const platform    = record['Platform'] || 'YouTube';
  const topic       = record['Topic'] || '';
  const category    = (record['Category'] || '').trim();

  const formats = s.formats || {};
  const formatInstructions = formats[contentType] || formats['default'] || '';
  const metadataInstructions = s.metadata_instructions || '';

  const skills = s.skills || {};
  const template = skills[category] || skills['default'] || '';

  if (!template) {
    const reason = 'No script skill configured for category "' + (category || 'none') + '" on client ' + (cfg.client_name || 'unknown') + '. Check Config_JSON on the {Client}::script row.';
    console.log('[3] ' + reason);
    out.push({ json: withDefaults({ _skip: true, cfg: cfg, record_id: recordId, reason: reason }, cfg) });
    continue;
  }

  const archetypes = Array.isArray(s.hook_archetypes) ? s.hook_archetypes : [];
  const selectedHook = archetypes.length ? archetypes[Math.floor(Math.random() * archetypes.length)] : {};
  const implications = Array.isArray(s.implication_phrases) ? s.implication_phrases : [];
  const selectedImplication = implications.length ? implications[Math.floor(Math.random() * implications.length)] : '';

  const transcriptChars = s.transcript_chars || 2000;
  const vars = {
    topic: topic,
    platform: platform,
    category: category,
    content_type: contentType,
    brand: cfg.brand_name || cfg.client_name || '',
    client: cfg.client_name || '',
    skill_name: cfg.skill_name || '',
    pattern: pattern['Reusable_Pattern'] || 'Hook > Value > CTA',
    hook_type: pattern['Hook Type'] || '',
    structure_tag: pattern['Structure_Tag'] || '',
    transcript: String(pattern['Transcript'] || '').substring(0, transcriptChars),
    format_instructions: formatInstructions,
    metadata_instructions: metadataInstructions,
    hook_archetype_name: selectedHook.name || '',
    hook_archetype_style: selectedHook.style || '',
    hook_archetype_instruction: selectedHook.instruction || '',
    implication_phrase: selectedImplication
  };

  const render = (tpl) => String(tpl).replace(/\{\{\s*([A-Za-z_]+)\s*\}\}/g, (m, k) => {
    const key = k.toLowerCase();
    return Object.prototype.hasOwnProperty.call(vars, key) ? String(vars[key]) : m;
  });

  // Fixed guard, always appended. The reference transcript belongs to another creator.
  const sourceGuard = s.source_guard || ('\n\nSOURCE USE - NON-NEGOTIABLE:\n'
    + 'The reference transcript above is another creator\'s published work. It is a STRUCTURAL reference only.\n'
    + '- Take from it only the hook archetype, pacing, scene order and rhetorical shape.\n'
    + '- Do NOT reuse its sentences, phrasing, examples, analogies, statistics, or specific claims.\n'
    + '- Do NOT paraphrase it line by line. Do NOT produce a reworded version of it.\n'
    + '- Every fact and figure in your script must come from the TOPIC and your own knowledge, not from the transcript.\n'
    + '- The finished script must stand on its own and must not be recognisable as a rewrite of the source.\n'
    + 'If the transcript is about a different subject than the TOPIC, use only its shape and write entirely fresh content.');

  // T-43: one automatic rewrite from the reviewer's feedback.
  let revision = '';
  if (record.mode === 'regenerate') {
    revision = '\n\nREVISION REQUEST - NON-NEGOTIABLE:\n'
      + 'Rewrite this script applying the reviewer\'s feedback. Keep the output format, bracketed scene labels, scene table and metadata lines required above. '
      + 'Address every point in the feedback and keep what the reviewer did not object to.\n\n'
      + 'PREVIOUS SCRIPT:\n' + String(record['Script'] || '').trim()
      + '\n\nREVIEWER FEEDBACK:\n' + String(record['Script_Feedback'] || '').trim();
  }

  out.push({ json: withDefaults({
    _skip: false,
    cfg: cfg,
    record_id: recordId,
    mode: record.mode || 'first',
    topic: topic,
    platform: platform,
    category: category,
    content_type: contentType,
    pattern_name: pattern['Reusable_Pattern'] || 'Unknown Pattern',
    prompt: render(template) + sourceGuard + revision
  }, cfg) });
}

console.log('[3] Records: ' + records.length + ' | Prompts built: ' + out.filter(o => !o.json._skip).length + ' | Rewrites: ' + records.filter(r => r.mode === 'regenerate').length);
return out;

const response = $input.item.json;
const promptData = $('3. Build Viral-Aware Prompt').item.json;
const cfg = promptData.cfg || {};
const s = cfg.script || {};

let fullResponse = '';
try {
  fullResponse = response.choices[0].message.content || '';
} catch (e) {
  fullResponse = 'ERROR: Script generation failed. Please retry.';
}

const extractField = (text, field) => {
  const lines = String(text).split('\n');
  const fieldUpper = field.toUpperCase();
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();
    if (line.toUpperCase().startsWith(fieldUpper + ':')) {
      let value = line.substring(line.indexOf(':') + 1).trim();
      for (let j = i + 1; j < lines.length; j++) {
        const next = lines[j].trim();
        if (!next) break;
        if (/^[A-Z][A-Z_]+:/.test(next)) break;
        value += '\n' + next;
      }
      return value.replace(/^\[.*?\]$/, '').trim();
    }
  }
  return '';
};

const metadataStart = fullResponse.search(/\n(?:INSTAGRAM_CAPTION|TIKTOK_CAPTION|LINKEDIN_CAPTION|YOUTUBE_CAPTION|MANYCHAT_COPY|HOOK_TYPE|THUMBNAIL|TAGS)[:\s]/i);
let rawScript = metadataStart > -1 ? fullResponse.substring(0, metadataStart).trim() : fullResponse.trim();
const metadataBlock = metadataStart > -1 ? fullResponse.substring(metadataStart) : '';

// The skills ask for a scene reference table after the script. It sits between the last
// bracketed label and the metadata, so its words must be removed BEFORE scene durations
// are measured or the final scene absorbs the whole table.
const rawTableStart = rawScript.search(/\n\s*\|/);
if (rawTableStart > -1) rawScript = rawScript.substring(0, rawTableStart).trim();

const sceneLabelMap = s.scene_labels || {};

const allLabelMatches = [...rawScript.matchAll(/^\*{0,2}\[([A-Z][A-Z\s\/]+)\]\*{0,2}\s*$/gm)];
const WORDS_PER_SECOND = (promptData.words_per_minute || 130) / 60;
let productionBrief = '';

if (allLabelMatches.length > 0) {
  const scenes = [];
  for (let i = 0; i < allLabelMatches.length; i++) {
    const labelRaw = allLabelMatches[i][1].trim();
    const label = sceneLabelMap[labelRaw] || labelRaw;
    const start = allLabelMatches[i].index + allLabelMatches[i][0].length;
    const end = i + 1 < allLabelMatches.length ? allLabelMatches[i + 1].index : rawScript.length;
    const sceneText = rawScript.substring(start, end).trim();
    const wordCount = sceneText.split(/\s+/).filter(w => w.length > 0).length;
    scenes.push({ label: label, wordCount: wordCount });
  }
  let cursor = 0;
  const briefLines = scenes.map(sc => {
    const duration = sc.wordCount / WORDS_PER_SECOND;
    const startSec = Math.round(cursor);
    cursor += duration;
    const endSec = Math.round(cursor);
    return sc.label + ': ' + startSec + '-' + endSec + 's';
  });
  productionBrief = briefLines.join('\n');
}

let script = rawScript
  .replace(/^.*?(?:script|reel|short|video)[^\n]*?-{2,}\s*\n?/i, '')
  .replace(/^\*{0,2}\[[\w\s\/]+\]\*{0,2}\s*\n?/gm, '')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

const tableStart = script.search(/\n\|[\s\w]+\|/);
if (tableStart > -1) script = script.substring(0, tableStart).trim();

const maxChars = promptData.max_script_chars || 5000;
if (script.length > maxChars) script = script.substring(0, maxChars).trimEnd();

const instagramCaption = extractField(metadataBlock || fullResponse, 'INSTAGRAM_CAPTION');
const linkedinCaption  = extractField(metadataBlock || fullResponse, 'LINKEDIN_CAPTION');
const hookType         = extractField(metadataBlock || fullResponse, 'HOOK_TYPE');
const thumbnailIdea    = extractField(metadataBlock || fullResponse, 'THUMBNAIL');

const topic = String(promptData.topic || '').toLowerCase();
const existingCategory = String(promptData.category || '').trim();
const scriptLower = script.toLowerCase();
const topicAndScript = topic + ' ' + scriptLower.substring(0, 500);

const categoryKeywords = s.category_keywords || {};
let detectedCategory = existingCategory;
const shouldAutoDetect = !existingCategory || existingCategory === 'Other';

if (shouldAutoDetect) {
  detectedCategory = s.default_category || 'Other';
  for (const cat of Object.keys(categoryKeywords)) {
    const kws = categoryKeywords[cat] || [];
    if (kws.some(kw => topicAndScript.includes(String(kw).toLowerCase()))) { detectedCategory = cat; break; }
  }
}

const categoryChanged = detectedCategory !== existingCategory;

const tagKeywords = s.tag_keywords || {};
const categoryToTag = s.category_to_tag || {};
const assigned = [];
for (const tag of Object.keys(tagKeywords)) {
  const kws = tagKeywords[tag] || [];
  const byCategory = categoryToTag[detectedCategory] === tag;
  if (byCategory || kws.some(kw => topic.includes(String(kw).toLowerCase()))) assigned.push(tag);
}
if (assigned.length === 0) assigned.push(s.default_tag || 'Other');

return { json: {
  cfg:               cfg,
  record_id:         promptData.record_id,
  script:            script,
  production_brief:  productionBrief,
  pattern_used:      promptData.pattern_name,
  tags:              assigned,
  detected_category: detectedCategory,
  category_changed:  categoryChanged,
  instagram_caption: instagramCaption,
  linkedin_caption:  linkedinCaption,
  hook_type:         hookType,
  thumbnail_idea:    thumbnailIdea
} };

// Swappable config comes from CONTROL as JSON, not from hardcoded values in this workflow.
// Clients.Config_JSON = client-wide defaults.
// Client_Outputs.Config_JSON where Key = '{Client}::script' = per-output override (shallow merge, output wins).
const OUTPUT_TYPE = 'script';

function parseJson(raw, label) {
  if (!raw) return {};
  try {
    const v = JSON.parse(raw);
    if (v && typeof v === 'object' && !Array.isArray(v)) return v;
    console.log('[0b] Config_JSON on ' + label + ' is not an object, ignoring');
    return {};
  } catch (e) {
    console.log('[0b] Invalid Config_JSON on ' + label + ': ' + e.message);
    return {};
  }
}

const outputs = $input.all().map(i => i.json);
const clients = $('0a. Load Clients').all().map(i => i.json);

const outByKey = {};
for (const o of outputs) {
  const key = (o['Key'] || '').trim().toLowerCase();
  if (key) outByKey[key] = o;
}

const out = [];
for (const c of clients) {
  const name = c['Client_Name'];
  if (!name) continue;
  if (c['Video_Enabled'] !== true) continue;
  if (!c['Video_Base_ID']) { console.log('[0b] ' + name + ' has no Video_Base_ID, skipping'); continue; }

  const clientCfg = parseJson(c['Config_JSON'], name);
  const o = outByKey[(name + '::' + OUTPUT_TYPE).toLowerCase()] || null;
  const outputCfg = o ? parseJson(o['Config_JSON'], name + '::' + OUTPUT_TYPE) : {};
  if (!o) console.log('[0b] No Client_Outputs row for ' + name + '::' + OUTPUT_TYPE + ', using client-level config only');

  const merged = { ...clientCfg, ...outputCfg };

  out.push({ json: {
    ...merged,
    client_name:      name,
    video_base_id:    c['Video_Base_ID'],
    brand_name:       c['Brand_Name'] || name,
    notes_stage_tag:  c['Notes_Stage_Tag'] || '',
    variation_count:  c['Variation_Count'] || null,
    output_type:      OUTPUT_TYPE,
    manus_project_id: o ? (o['Manus_Project_ID'] || '') : '',
    skill_name:       o ? (o['Skill_Name'] || '') : '',
    skill_fallback:   o ? (o['Skill_Fallback'] || '') : ''
  } });
}

console.log('[0b] Clients to process: ' + out.length);
return out;

const loop = $('0c. Client Loop');
let cfg = null;
try { cfg = loop.item.json; } catch (e) { cfg = null; }
if (!cfg || !cfg.video_base_id) { throw new Error('Could not resolve client config for this iteration.'); }
// started_at is captured here so the notes block can report how long the run took.
return { json: { ...$input.item.json, cfg, started_at: new Date().toISOString() } };

// Tagged-block write: strip only this stage's block, keep every other stage's notes.
const fresh = $input.item.json || {};
const d = $('5. Preserve Data + Extract Script').item.json;
const cfg = d.cfg || {};
const s = cfg.script || {};

// T-43: gate mode by record ID from 1d. Fail closed - without it the revision count cannot be set safely.
const gate = $('1d. Approval Check').all().map(i => i.json).find(r => r.id === d.record_id);
if (!gate) throw new Error('5y: no Approval Check entry for record ' + d.record_id);
const mode = gate.mode || 'first';
const prevCount = Number(gate['Script_Revision_Count'] || 0);
const revisionCount = mode === 'regenerate' ? 1 : prevCount;

const f = (fresh.fields && typeof fresh.fields === 'object') ? fresh.fields : fresh;
const freshNotes = (f && typeof f.Reel_Notes === 'string') ? f.Reel_Notes : '';

const sep = s.notes_separator || '==============================';
const STAGE_TAG = s.stage_tag || 'SCRIPT (WF04)';
const esc = t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const blockRe = new RegExp('\\n*' + esc(sep) + '\\n' + esc(STAGE_TAG) + '[\\s\\S]*?(?=(\\n' + esc(sep) + '\\n)|$)', 'g');
const notesBase = freshNotes.replace(blockRe, '').trim();

let triggered = '';
let runtime = 'unknown';
try {
  const raw = $('1c. Attach Config').first().json.started_at || '';
  triggered = raw ? raw.substring(0, 16).replace('T', ' ') : '';
  const st = Date.parse(raw);
  if (st) { const secs = Math.max(0, Math.round((Date.now() - st) / 1000)); runtime = Math.floor(secs / 60) + 'm ' + (secs % 60) + 's'; }
} catch (e) {}

const stamp = new Date().toISOString().substring(0, 16).replace('T', ' ');
const block = sep + '\n' + STAGE_TAG
  + '\nTriggered: ' + triggered
  + '\nUpdated: ' + stamp
  + '\nRun time: ' + runtime
  + '\nStage: Complete'
  + '\nScript_Approval: Pending' + (mode === 'regenerate' ? ' (revision 1 from Script_Feedback)' : ' (first script)')
  + '\nPattern: ' + (d.pattern_used || '')
  + '\nHook Type: ' + (d.hook_type || '')
  + '\nCategory: ' + (d.detected_category || '') + (d.category_changed ? ' (auto-detected)' : '')
  + '\nThumbnail: ' + (d.thumbnail_idea || '')
  + '\n\n--- INSTAGRAM ---\n' + (d.instagram_caption || '')
  + '\n\n--- LINKEDIN ---\n' + (d.linkedin_caption || '');

const notesFinal = (notesBase ? notesBase + '\n\n' : '') + block;

return { json: { ...d, mode: mode, script_revision_count: revisionCount, reel_notes_final: notesFinal, run_time: runtime } };

// T-43 gate check. Gate 1: Production_Approval must be ticked before any script work.
// Gate 2: Script_Approval = Revision Required -> one automatic rewrite from Script_Feedback, then manual edit.
// Field NAMES only - field IDs differ per base.
const recs = $input.all().map(i => i.json).filter(r => r && r.id);
const out = recs.map(r => {
  const sa = String(r['Script_Approval'] || '').trim();
  const fb = String(r['Script_Feedback'] || '').trim();
  const rc = Number(r['Script_Revision_Count'] || 0);
  let route = 'generate', mode = 'first', note = '', status = '';
  if (r['Production_Approval'] !== true) {
    route = 'hold'; mode = 'unapproved'; note = 'Not approved for production: skipped'; status = 'Idea';
  } else if (sa === 'Revision Required' && rc >= 1) {
    route = 'hold'; mode = 'second_rejection'; note = 'Manual edit needed'; status = 'Needs Review';
  } else if (sa === 'Revision Required' && fb) {
    mode = 'regenerate';
  } else if (sa === 'Revision Required') {
    route = 'hold'; mode = 'no_feedback'; note = 'Manual edit needed: Revision Required with empty Script_Feedback'; status = 'Needs Review';
  }
  return { ...r, route: route, mode: mode, gate_note: note, gate_status: status, base_id: (r.cfg || {}).video_base_id || '' };
});
const hasGenerate = out.some(o => o.route === 'generate');
console.log('[1d] Records: ' + out.length + ' | generate: ' + out.filter(o => o.route === 'generate').length + ' | hold: ' + out.filter(o => o.route === 'hold').length);
return out.map(o => ({ json: { ...o, has_generate: hasGenerate } }));

// T-43 gate hold: no model call. Re-read notes, replace only the SCRIPT (WF04) block, set Status.
const fresh = $input.item.json || {};
const g = $('1e. Generate?').item.json;
const s = (g.cfg || {}).script || {};
const f = (fresh.fields && typeof fresh.fields === 'object') ? fresh.fields : fresh;
const freshNotes = (f && typeof f.Reel_Notes === 'string') ? f.Reel_Notes : '';

const sep = s.notes_separator || '==============================';
const STAGE_TAG = s.stage_tag || 'SCRIPT (WF04)';
const esc = t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const blockRe = new RegExp('\\n*' + esc(sep) + '\\n' + esc(STAGE_TAG) + '[\\s\\S]*?(?=(\\n' + esc(sep) + '\\n)|$)', 'g');
const prevBlock = ((freshNotes.match(blockRe) || [''])[0] || '').trim();
const notesBase = freshNotes.replace(blockRe, '').trim();

const stamp = new Date().toISOString().substring(0, 16).replace('T', ' ');
let block = sep + '\n' + STAGE_TAG + '\nUpdated: ' + stamp + '\n' + g.gate_note;
if (g.mode !== 'unapproved' && prevBlock) {
  const prevBody = prevBlock.split('\n').slice(2).filter(l => !/^(Triggered|Updated|Run time|Stage):/.test(l) && l.indexOf('Manual edit needed') !== 0).join('\n').trim();
  if (prevBody) block += '\n\n' + prevBody;
}
const notesFinal = (notesBase ? notesBase + '\n\n' : '') + block;

return { json: { record_id: g.id, base_id: g.base_id, gate_status: g.gate_status, mode: g.mode, has_generate: g.has_generate === true, reel_notes_final: notesFinal } };
